fetch('https://api.example.com/users')
  .then(res => res.json())
  .then(users => {
    const ul = document.querySelector('#userList');
    users.forEach(u => {
      const li = document.createElement('li');
      li.textContent = u.name;
      ul.appendChild(li);
    });
  });

